"""Small plugin interface: run(gates, budget, seed) -> Proposal or None."""
import itertools
import random
import time
from .core import Gate, Proposal, REV, cost, commute, signature
from .vendor import k099


def cancellation(gates, budget, seed):
    # Reuse K099's known implementation for the supported intersection.
    lines = [g.text() for g in gates]
    out, events, _ = k099.cancel(lines, min(budget['span'], 128))
    from .core import parse
    candidate = [parse(x) for x in out]
    if any(g is None for g in candidate):
        raise ValueError('vendor emitted unsupported syntax')
    if cost(candidate) < cost(gates):
        return Proposal(candidate, {'pairs': events, 'implementation': 'K099'})
    # K099 does not canonicalize CSWAP/symmetric controls; handle CSWAP explicitly.
    for i, g in enumerate(gates):
        if g.op != 'CSWAP':
            continue
        for j in range(i+1, len(gates)):
            if gates[j] == g:
                return Proposal(gates[:i]+gates[i+1:j]+gates[j+1:], {'identity': 'CSWAP involution'})
            if not commute(g, gates[j]):
                break
    return None


def factor(gates, budget, seed):
    """ab XOR ac = a(b XOR c); full-table proof guards all intervening effects."""
    for i, g in enumerate(gates):
        if g.op != 'CCX':
            continue
        for j in range(i+1, len(gates)):
            h = gates[j]
            if h.op != 'CCX' or g.q[-1] != h.q[-1]:
                continue
            shared = set(g.q[:2]) & set(h.q[:2])
            if len(shared) != 1:
                continue
            a = next(iter(shared))
            b = next(iter(set(g.q[:2])-shared))
            c = next(iter(set(h.q[:2])-shared))
            # Only move h across an explicitly commuting interval.
            if not all(commute(h, x) for x in gates[i+1:j]):
                continue
            rep = [Gate('CX', (b,c)), Gate('CCX', tuple(sorted((a,c)))+(g.q[2],)), Gate('CX',(b,c))]
            return Proposal(gates[:i]+rep+gates[i+1:j]+gates[j+1:], {'identity': 'shared-control XOR factor'})
    return None


def affine(gates, budget, seed):
    """GF(2) Gaussian elimination; only unconditional X/CX/SWAP regions."""
    if any(g.op not in {'X', 'CX', 'SWAP'} for g in gates):
        return None
    wires = sorted({q for g in gates for q in g.q})
    index = {q:i for i,q in enumerate(wires)}
    rows = [1 << i for i in range(len(wires))]
    bias = [0] * len(wires)
    for g in gates:
        q = [index[x] for x in g.q]
        if g.op == 'X': bias[q[0]] ^= 1
        elif g.op == 'CX':
            rows[q[1]] ^= rows[q[0]]; bias[q[1]] ^= bias[q[0]]
        else:
            rows[q[0]], rows[q[1]] = rows[q[1]], rows[q[0]]
            bias[q[0]], bias[q[1]] = bias[q[1]], bias[q[0]]
    elimination = []
    for col in range(len(wires)):
        pivot = next(j for j in range(col,len(wires)) if (rows[j]>>col)&1)
        if pivot != col:
            rows[pivot], rows[col] = rows[col], rows[pivot]
            elimination.append(Gate('SWAP',(wires[col],wires[pivot])))
        for row in range(len(wires)):
            if row != col and (rows[row]>>col)&1:
                rows[row] ^= rows[col]
                elimination.append(Gate('CX',(wires[col],wires[row])))
    candidate = list(reversed(elimination)) + [Gate('X',(wires[i],)) for i,x in enumerate(bias) if x]
    if cost(candidate) < cost(gates):
        return Proposal(candidate, {'identity': 'GF2 affine matrix resynthesis'})
    return None


def mitm(gates, budget, seed):
    """Bounded bidirectional permutation search, including inequivalent intermediates.

    Stores at most max_states total states; never claims optimality on timeout/cap.
    Restricted to <=3 wires to keep permutation objects bounded.
    """
    wires = sorted({q for g in gates for q in g.q})
    if len(wires)>3 or any(g.op not in REV for g in gates):
        return None
    n = len(wires)
    alphabet = [Gate('X',(q,)) for q in wires]
    alphabet += [Gate('CX',q) for q in itertools.permutations(wires,2)]
    alphabet += [Gate('CCX',tuple(sorted(set(wires)-{t}))+(t,)) for t in wires] if n==3 else []
    rng = random.Random(seed); rng.shuffle(alphabet)
    identity = tuple(range(1<<n))
    target = tuple(x for x,p in signature(gates,wires))
    permutations = [(g,tuple(x for x,p in signature([g],wires))) for g in alphabet]
    forward = {identity: ()}; backward = {target: ()}
    fronts = [forward.copy(), backward.copy()]
    tables = [forward, backward]
    deadline = time.monotonic()+budget['seconds']
    best = None
    for level in range(budget['depth']):
        side = level % 2
        nxt = {}
        for state, path in fronts[side].items():
            for gate, perm in permutations:
                if time.monotonic()>deadline or sum(map(len,tables))>=budget['max_states']:
                    return best
                new = tuple(perm[x] for x in state)
                newpath = path+(gate,)
                if new in tables[1-side]:
                    other = tables[1-side][new]
                    candidate = list(newpath)+list(reversed(other)) if side==0 else list(other)+list(reversed(newpath))
                    if cost(candidate)<cost(gates) and (best is None or cost(candidate)<cost(best.gates)):
                        best = Proposal(candidate, {'search': 'bidirectional', 'levels': level+1,
                            'states': sum(map(len,tables)), 'optimality_claim': False})
                # Keep a cheaper path to each function, not merely the shortest path.
                previous = tables[side].get(new)
                if previous is None or cost(newpath)<cost(previous):
                    tables[side][new]=newpath; nxt[new]=newpath
        fronts[side]=nxt
        if not nxt:
            break
    return best


def stochastic(gates, budget, seed):
    """Annealed algebraic rewriting: all moves are independently exact.

    Random ordering/neutral commutation exposes new adjacent patterns; does not
    claim an unrestricted circuit-space annealer or legacy beam functionality.
    """
    rng = random.Random(seed)
    state = list(gates)
    best = list(gates)
    deadline = time.monotonic()+budget['seconds']
    for step in range(budget['max_states']):
        if time.monotonic()>=deadline:
            break
        if len(state)>1:
            i=rng.randrange(len(state)-1)
            if commute(state[i],state[i+1]): state[i],state[i+1]=state[i+1],state[i]
        proposal = (factor if step%2 else cancellation)(state,budget,seed+step)
        if proposal:
            state=proposal.gates
            if cost(state)<cost(best): best=list(state)
        if len(best)==0:
            break
    if cost(best)<cost(gates):
        return Proposal(best, {'search': 'random exact rewrite walk', 'steps': step+1})
    return None


from .smt import synthesize as smt

PLUGINS = {'smt':smt, 'cancel': cancellation, 'affine': affine, 'factor': factor,
           'mitm': mitm, 'stochastic': stochastic}

store.py:
"""Transactional experiment registry. A single controller owns a database lock."""
import json
import sqlite3
import time
from pathlib import Path
from .core import sha


class Store:
    def __init__(self, path):
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        self.db = sqlite3.connect(path)
        self.db.row_factory = sqlite3.Row
        self.db.executescript('''
        PRAGMA journal_mode=WAL;
        PRAGMA foreign_keys=ON;
        CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY, value TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS candidates(
            sha TEXT PRIMARY KEY, parent TEXT, path TEXT NOT NULL,
            proof TEXT NOT NULL, official_status TEXT NOT NULL DEFAULT 'NOT_RUN',
            score REAL, metrics TEXT, created REAL NOT NULL);
        CREATE TABLE IF NOT EXISTS experiments(
            key TEXT PRIMARY KEY, parent TEXT NOT NULL, method TEXT NOT NULL,
            config TEXT NOT NULL, region TEXT NOT NULL, canonical TEXT NOT NULL,
            seed INTEGER NOT NULL, status TEXT NOT NULL, equivalence TEXT,
            candidate TEXT, verifier_result TEXT, score REAL, reason TEXT,
            seconds REAL NOT NULL DEFAULT 0, detail TEXT);
        CREATE INDEX IF NOT EXISTS experiment_method ON experiments(method,status);
        CREATE TABLE IF NOT EXISTS history(
            key TEXT PRIMARY KEY, method TEXT, configuration TEXT, candidate TEXT,
            equivalence_status TEXT, verifier_result TEXT, score REAL,
            reason TEXT, provenance TEXT NOT NULL, raw TEXT NOT NULL);
        ''')
        self.db.commit()

    def get(self, key, default=None):
        row=self.db.execute('SELECT value FROM meta WHERE key=?',(key,)).fetchone()
        return json.loads(row[0]) if row else default

    def set(self, key, value):
        self.db.execute('INSERT OR REPLACE INTO meta VALUES (?,?)',(key,json.dumps(value)))
        self.db.commit()

    def recover(self):
        self.db.execute("UPDATE experiments SET status='PENDING',reason='Recovered interrupted task' WHERE status='RUNNING'")
        self.db.commit()

    def add(self, parent, method, config, region, canonical, seed, commit=True):
        # Canonical no-result experiments are shared across wire renaming.
        key=sha(json.dumps([method,config,canonical,seed],sort_keys=True))
        # Successful jobs are reapplied on new parents/occurrences, without
        # suppressing a useful repeated motif as an 'equivalent experiment'.
        row=self.db.execute('SELECT status FROM experiments WHERE key=?',(key,)).fetchone()
        if row and row[0]=='PENDING':
            self.db.execute('UPDATE experiments SET parent=?,region=? WHERE key=?',(parent,json.dumps(region),key))
        if row and row[0]=='LOCAL_IMPROVEMENT':
            key=sha(key+parent+json.dumps(region))
        self.db.execute('INSERT OR IGNORE INTO experiments(key,parent,method,config,region,canonical,seed,status) VALUES (?,?,?,?,?,?,?,?)',
            (key,parent,method,json.dumps(config,sort_keys=True),json.dumps(region),canonical,seed,'PENDING'))
        if commit: self.db.commit()
        return key

    def finish(self,key,status,reason,seconds=0,equivalence=None,candidate=None,detail=None):
        self.db.execute('UPDATE experiments SET status=?,reason=?,seconds=?,equivalence=?,candidate=?,detail=? WHERE key=?',
            (status,reason,seconds,json.dumps(equivalence),candidate,json.dumps(detail),key))
        if candidate:
            receipt=self.db.execute('SELECT metrics,score FROM candidates WHERE sha=?',(candidate,)).fetchone()
            if receipt and receipt[0]:
                self.db.execute('UPDATE experiments SET verifier_result=?,score=? WHERE key=?',(receipt[0],receipt[1],key))
        self.db.commit()

    def candidate(self, digest, parent, path, proof):
        self.db.execute('INSERT OR IGNORE INTO candidates(sha,parent,path,proof,created) VALUES (?,?,?,?,?)',
            (digest,parent,str(path),json.dumps(proof),time.time()))
        self.db.commit()

    def receipt(self, digest, result):
        self.db.execute('UPDATE candidates SET official_status=?,score=?,metrics=? WHERE sha=?',
            (result['status'],result.get('score'),json.dumps(result),digest))
        self.db.execute('UPDATE experiments SET verifier_result=?,score=? WHERE candidate=?',
            (json.dumps(result),result.get('score'),digest))
        self.db.commit()

    def export(self, path):
        with Path(path).open('w') as stream:
            stream.write('{')
            for i,table in enumerate(('meta','experiments','candidates','history')):
                if i: stream.write(',')
                stream.write(json.dumps(table)+':[')
                first=True
                for row in self.db.execute('SELECT * FROM '+table):
                    if not first: stream.write(',')
                    stream.write(json.dumps(dict(row)));first=False
                stream.write(']')
            stream.write('}\n')

    def close(self):
        self.db.execute('PRAGMA wal_checkpoint(TRUNCATE)')
        self.db.close()

verification.py:
"""Verifier isolation and strict full-domain receipts.

The official CLI is invoked through a user-supplied argv contract, never a shell.
The local asset SHA, exact command, seeds, and output are retained. Exit code
alone, PASS in prose, a prefix PASS, or non-finite score can never promote.
"""
import hashlib
import json
import math
import os
import resource
import signal
import subprocess
import sys
from pathlib import Path


def limits(memory_mb, cpus):
    def apply():
        resource.setrlimit(resource.RLIMIT_AS,(memory_mb*1024**2,)*2)
        resource.setrlimit(resource.RLIMIT_CORE,(0,0))
        resource.setrlimit(resource.RLIMIT_FSIZE,(16*1024**2,)*2)
        if hasattr(os,'sched_getaffinity'):
            allowed=sorted(os.sched_getaffinity(0))[:cpus]
            os.sched_setaffinity(0,set(allowed))
    return apply


def run_process(argv, log, timeout, memory_mb=2048, cpus=1):
    """File-backed output, process-group timeout, no indefinite descendants."""
    env=os.environ.copy()
    env.update({x:str(cpus) for x in ('OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS')})
    with Path(log).open('wb') as stream:
        proc=subprocess.Popen(argv,stdout=stream,stderr=subprocess.STDOUT,
            start_new_session=True,preexec_fn=limits(memory_mb,cpus),env=env)
        try:
            code=proc.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            os.killpg(proc.pid,signal.SIGKILL); proc.wait()
            return {'exit_code':None,'status':'TIMEOUT','log':str(log)}
        # No task may leave background solver children running.
        try: os.killpg(proc.pid,signal.SIGKILL)
        except ProcessLookupError: pass
    return {'exit_code':code,'status':'EXITED','log':str(log)}


def parse_receipt(text, exit_code, contract):
    decoder=json.JSONDecoder()
    records=[]
    # Verifier versions emit either a JSON object or banner + multiline JSON.
    # Only complete dictionaries with status qualify; strings mentioning PASS do not.
    offset=0
    while offset<len(text):
        i=text.find('{',offset)
        if i<0: break
        try:
            value,end=decoder.raw_decode(text,i)
            offset=end  # Nested status objects cannot override their parent.
            if isinstance(value,dict) and 'status' in value: records.append(value)
        except ValueError:
            offset=i+1
        if len(records)>100:
            return {'status':'UNPARSEABLE','reason':'Too many verifier documents'}
    if not records:
        return {'status':'UNPARSEABLE','reason':'No structured verifier result'}
    record=records[-1]
    score=record.get('score')
    if exit_code!=0 or record.get('status')!='PASS':
        return {'status':'FAIL','metrics':record,'reason':'Nonzero exit or no explicit PASS'}
    if isinstance(score,bool) or not isinstance(score,(int,float)) or not math.isfinite(score):
        return {'status':'INVALID_SCORE','metrics':record}
    expected=contract['full_shots']
    if record.get('verified_shots')!=expected:
        return {'status':'PARTIAL_OR_UNKNOWN_DOMAIN','metrics':record,
                'reason':f'Expected verified_shots={expected}'}
    # Required official metrics, with version-configurable exact field mapping.
    fields=contract['fields']
    missing=[name for name,field in fields.items() if field not in record]
    if missing:
        return {'status':'INCOMPLETE_METRICS','metrics':record,'reason':str(missing)}
    for name,field in fields.items():
        value=record[field]
        if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value):
            return {'status':'INVALID_METRICS','metrics':record,'reason':name}
    return {'status':'PASS_FULL','score':score,'metrics':record,
            'normalized_metrics':{name:record[field] for name,field in fields.items()}}


def verify(candidate, out, contract, timeout, memory_mb, cpus, remaining):
    out=Path(out); out.mkdir(parents=True,exist_ok=True)
    candidate=Path(candidate).resolve()
    raw=candidate.read_bytes()
    digest=hashlib.sha256(raw).hexdigest()
    script=Path(contract['script']).resolve()
    if not script.is_file():
        return {'status':'UNAVAILABLE','reason':f'Official verifier absent: {script}'}
    actual=hashlib.sha256(script.read_bytes()).hexdigest()
    if actual!=contract['script_sha256']:
        return {'status':'VERIFIER_SHA_MISMATCH','actual':actual}
    receipts=[]
    import time
    start=time.monotonic()
    for seed in contract['seeds']:
        budget=min(timeout,remaining-(time.monotonic()-start))
        if budget<=0:
            return {'status':'BUDGET_EXHAUSTED','runs':receipts}
        substitutions={'python':sys.executable,'script':str(script),'candidate':str(candidate),
                       'seed':str(seed),'workers':str(cpus),'binary':str(out/'candidate.kmb')}
        # Optional conversion uses an inspected local official interface/argv.
        if contract.get('prepare_argv'):
            argv=[token.format(**substitutions) for token in contract['prepare_argv']]
            prep=run_process(argv,out/f'prepare-{seed}.log',budget,memory_mb,cpus)
            if prep.get('exit_code')!=0:
                return {'status':'PREPARE_FAILED','runs':receipts,'prepare':prep}
        budget=min(timeout,remaining-(time.monotonic()-start))
        if budget<=0:
            return {'status':'BUDGET_EXHAUSTED','runs':receipts}
        argv=[token.format(**substitutions) for token in contract['argv']]
        log=out/f'verifier-{seed}.log'
        status=run_process(argv,log,budget,memory_mb,cpus)
        if status['status']=='TIMEOUT':
            result=status
        elif log.stat().st_size>8*1024**2:
            result={'status':'OUTPUT_TOO_LARGE','log':str(log)}
        else:
            result=parse_receipt(log.read_text(errors='replace'),status['exit_code'],contract)
        result.update({'argv':argv,'seed':seed,'verifier_sha256':actual,
                       'candidate_sha256':digest,'log':str(log)})
        receipts.append(result)
        (out/'receipt.json').write_text(json.dumps({'runs':receipts},indent=2)+'\n')
        if result['status']!='PASS_FULL':
            return {'status':result['status'],'runs':receipts}
    if hashlib.sha256(candidate.read_bytes()).hexdigest()!=digest:
        return {'status':'CANDIDATE_CHANGED','runs':receipts}
    # Conservative score across the configured seeds.
    scores=[r['score'] for r in receipts]
    return {'status':'PASS_FULL','score':min(scores) if contract['direction']=='maximize' else max(scores),
            'runs':receipts,'candidate_sha256':digest,'verifier_sha256':actual}


def validate_contract(contract):
    if contract['direction'] not in ('maximize','minimize'):
        raise ValueError('direction must be maximize or minimize')
    if not contract.get('seeds') or not all(type(s) is int for s in contract['seeds']):
        raise ValueError('nonempty integer seeds required')
    if type(contract.get('full_shots')) is not int or contract['full_shots']<=0:
